40	#ifndef CONFIG_ARCH_USE_S_MODE
41	static inline uint64_t riscv_mtimer_get(uintreg_t mtime_addr)
42	{
43	#  if CONFIG_ARCH_RV_MMIO_BITS == 64
44	  /* mtime_addr is -1, means this SoC:
45	   * 1. does NOT support 64bit/DWORD write for the mtimer compare value regs,
46	   * 2. has NO memory mapped regs which hold the value of mtimer counter,
47	   *    it could be read from the CSR "time".
48	   */
49	
50	  return -1 == mtime_addr ? READ_CSR(CSR_TIME) : getreg64(mtime_addr);
51	#  else
52	  uint32_t hi;
53	  uint32_t lo;
54	
55	  do
56	    {
57	      hi = getreg32(mtime_addr + 4);
58	      lo = getreg32(mtime_addr);
59	    }
60	  while (getreg32(mtime_addr + 4) != hi);
61	
62	  return ((uint64_t)hi << 32) | lo;
63	#  endif
64	}
65	
66	static inline
67	void riscv_mtimer_set(uintreg_t mtime_addr,
68	                      uintreg_t mtimecmp_addr, uint64_t value)
69	{
70	#  if CONFIG_ARCH_RV_MMIO_BITS == 64
71	  if (-1 != mtime_addr)
72	    {
73	      putreg64(value, mtimecmp_addr);
74	    }
75	  else
76	#  endif
77	    {
78	      irqstate_t flags = up_irq_save();
79	      putreg32(UINT32_MAX, mtimecmp_addr + 4);
80	      putreg32(value, mtimecmp_addr);
81	      putreg32(value >> 32, mtimecmp_addr + 4);
82	      up_irq_restore(flags);
83	    }
84	
85	  UP_DSB();
86	}
87	
88	#else
89	
90	#  ifdef CONFIG_ARCH_RV_EXT_SSTC
91	static inline void riscv_write_stime(uint64_t value)
92	{
93	#    ifdef CONFIG_ARCH_RV64
94	  WRITE_CSR(CSR_STIMECMP, value);
95	#    else
96	  irqstate_t flags = up_irq_save();
97	  WRITE_CSR(CSR_STIMECMP, (uint32_t)value);
98	  WRITE_CSR(CSR_STIMECMPH, (uint32_t)(value >> 32));
99	  up_irq_restore(flags);
100	#    endif /* CONFIG_ARCH_RV64 */
101	}
102	#  endif /* CONFIG_ARCH_RV_EXT_SSTC */
