48	
49	void up_irqinitialize(void)
50	{
51	  uintptr_t claim;
52	
53	  /* Disable S-Mode interrupts */
54	
55	  up_irq_save();
56	
57	  /* Attach the common interrupt handler */
58	
59	  riscv_exception_attach();
60	
61	  /* Disable all global interrupts */
62	
63	  putreg32(0x0, SG2000_PLIC_ENABLE1);
64	  putreg32(0x0, SG2000_PLIC_ENABLE2);
65	
66	  /* Clear pendings in PLIC */
67	
68	  claim = getreg32(SG2000_PLIC_CLAIM);
69	  putreg32(claim, SG2000_PLIC_CLAIM);
70	
71	  /* Colorize the interrupt stack for debug purposes */
72	
73	#if defined(CONFIG_STACK_COLORATION) && CONFIG_ARCH_INTERRUPTSTACK > 15
74	  size_t intstack_size = (CONFIG_ARCH_INTERRUPTSTACK & ~15);
75	  riscv_stack_color(g_intstackalloc, intstack_size);
76	#endif
77	
78	  /* Set priority for all global interrupts to 1 (lowest) */
79	
80	  int id;
81	
82	  for (id = 1; id <= NR_IRQS; id++)
83	    {
84	      putreg32(1, (uintptr_t)(SG2000_PLIC_PRIORITY + 4 * id));
85	    }
86	
87	  /* Set irq threshold to 0 (permits all global interrupts) */
88	
89	  putreg32(0, SG2000_PLIC_THRESHOLD);
90	
91	#ifdef CONFIG_SMP
92	  /* Clear IPI for CPU0 */
93	
94	  riscv_ipi_clear(0);
95	
96	  up_enable_irq(RISCV_IRQ_SOFT);
97	#endif
98	
99	#ifndef CONFIG_SUPPRESS_INTERRUPTS
100	
101	  /* And finally, enable interrupts */
102	
103	  riscv_color_intstack();
104	  up_irq_enable();
105	#endif
106	}
107	
108	/****************************************************************************
109	 * Name: up_disable_irq
110	 *
111	 * Description:
112	 *   Disable the IRQ specified by 'irq'
113	 *
114	 ****************************************************************************/
115	
116	void up_disable_irq(int irq)
117	{
118	  int extirq;
119	
120	  if (irq == RISCV_IRQ_SOFT)
121	    {
122	      /* Read sstatus & clear software interrupt enable in sie */
123	
124	      CLEAR_CSR(CSR_IE, IE_SIE);
125	    }
126	  else if (irq == RISCV_IRQ_TIMER)
127	    {
128	      /* Read sstatus & clear timer interrupt enable in sie */
129	
130	      CLEAR_CSR(CSR_IE, IE_TIE);
131	    }
132	  else if (irq > RISCV_IRQ_EXT)
133	    {
134	      extirq = irq - RISCV_IRQ_EXT;
135	
136	      /* Clear enable bit for the irq */
137	
138	      if (0 <= extirq && extirq <= 63)
139	        {
140	          modifyreg32(SG2000_PLIC_ENABLE1 + (4 * (extirq / 32)),
141	                      1 << (extirq % 32), 0);
142	        }
143	      else
144	        {
145	          PANIC();
146	        }
147	    }
148	}
149	
150	/****************************************************************************
151	 * Name: up_enable_irq
152	 *
153	 * Description:
154	 *   Enable the IRQ specified by 'irq'
155	 *
156	 ****************************************************************************/
157	
158	void up_enable_irq(int irq)
159	{
160	  int extirq;
161	
162	  if (irq == RISCV_IRQ_SOFT)
163	    {
164	      /* Read sstatus & set software interrupt enable in sie */
165	
166	      SET_CSR(CSR_IE, IE_SIE);
167	    }
168	  else if (irq == RISCV_IRQ_TIMER)
169	    {
170	      /* Read sstatus & set timer interrupt enable in sie */
171	
172	      SET_CSR(CSR_IE, IE_TIE);
173	    }
174	  else if (irq > RISCV_IRQ_EXT)
175	    {
176	      extirq = irq - RISCV_IRQ_EXT;
177	
178	      /* Set enable bit for the irq */
179	
180	      if (0 <= extirq && extirq <= 63)
181	        {
182	          modifyreg32(SG2000_PLIC_ENABLE1 + (4 * (extirq / 32)),
183	                      0, 1 << (extirq % 32));
184	        }
185	      else
186	        {
187	          PANIC();
188	        }
189	    }
190	}
191	
192	irqstate_t up_irq_enable(void)
193	{
194	  irqstate_t oldstat;
195	
196	  /* Enable external interrupts (sie) */
197	
198	  SET_CSR(CSR_IE, IE_EIE);
199	
200	  /* Read and enable global interrupts (sie) in sstatus */
201	
202	  oldstat = READ_AND_SET_CSR(CSR_STATUS, STATUS_IE);
203	
204	  return oldstat;
205	}
