45	static inline sbiret_t sbi_ecall(unsigned int extid, unsigned int fid,
46	                                 uintreg_t parm0, uintreg_t parm1,
47	                                 uintreg_t parm2, uintreg_t parm3,
48	                                 uintreg_t parm4, uintreg_t parm5)
49	{
50	  register long r0 asm("a0") = (long)(parm0);
51	  register long r1 asm("a1") = (long)(parm1);
52	  register long r2 asm("a2") = (long)(parm2);
53	  register long r3 asm("a3") = (long)(parm3);
54	  register long r4 asm("a4") = (long)(parm4);
55	  register long r5 asm("a5") = (long)(parm5);
56	  register long r6 asm("a6") = (long)(fid);
57	  register long r7 asm("a7") = (long)(extid);
58	  sbiret_t ret;
59	
60	  asm volatile
61	    (
62	     "ecall"
63	     : "+r"(r0), "+r"(r1)
64	     : "r"(r2), "r"(r3), "r"(r4), "r"(r5), "r"(r6), "r"(r7)
65	     : "memory"
66	     );
67	
68	  ret.error = r0;
69	  ret.value = (uintreg_t)r1;
70	
71	  return ret;
72	}
