78	int sbi_err_map_errno(intreg_t err)
79	{
80	  switch (err)
81	  {
82	    case SBI_SUCCESS:
83	      return 0;
84	    case SBI_ERR_DENIED:
85	      return -EPERM;
86	    case SBI_ERR_INVALID_PARAM:
87	      return -EINVAL;
88	    case SBI_ERR_INVALID_ADDRESS:
89	      return -EFAULT;
90	    case SBI_ERR_NOT_SUPPORTED:
91	    case SBI_ERR_FAILED:
92	    default:
93	      return -ENOTSUP;
94	  };
95	}
