1383	 *
1384	 * Description:
1385	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1386	 *
1387	 ****************************************************************************/
1388	
1389	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1390	{
1391	  FAR struct sg2000_eth_priv_s *priv =
1392	      (FAR struct sg2000_eth_priv_s *)dev;
1393	  int ret;
1394	
1395	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1396	
1397	  /* Ensure GMAC clocks and resets are configured */
1398	
1399	  gmac_clock_enable();
1400	
1401	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1402	
1403	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1404	
1405	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1406	  up_mdelay(10);
1407	
1408	  ret = mdio_verify_phy(priv->gmac_base);
1409	  if (ret < 0)
1410	    {
1411	      nerr("ERROR: MDIO PHY not responding: %d\n", ret);
1412	      return ret;
1413	    }
1414	
1415	  syslog(LOG_INFO, "sg2000_eth: MDIO operational "
1416	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1417	         getreg32(priv->gmac_base + GMAC_MII_ADDR),
1418	         getreg32(priv->gmac_base + GMAC_MII_DATA));
1419	
1420	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1421	
1422	  ret = phy_config_init(priv);
1423	  if (ret < 0)
1424	    {
1425	      nerr("ERROR: PHY init failed: %d\n", ret);
1426	      return ret;
1427	    }
1428	
1429	  ret = dma_soft_reset(priv->gmac_base);
1430	  if (ret < 0)
1431	    {
1432	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1433	             "diagnostics: %d\n", ret);
1434	      return ret;
1435	    }
1436	
1437	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1438	    {
1439	      ret = alloc_dma(priv);
1440	      if (ret < 0)
1441	        {
1442	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1443	          return ret;
1444	        }
1445	    }
1446	
1447	  init_desc_and_dma(priv);
1448	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1449	  start_mac_and_dma(priv);
1450	  rx_doorbell(priv);
1451	
1452	  /* Diagnostic: verify DMA state machines after initialization.
1453	   * TS[22:20]=TX state, RS[19:17]=RX state.  Both should show Running.
1454	   */
1455	
1456	  {
1457	    uint32_t csr5 = getreg32(priv->gmac_base + DMA_STATUS);
1458	    uint32_t csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1459	    unsigned int tx_state = (csr5 >> 20) & 0x7;
1460	    unsigned int rx_state = (csr5 >> 17) & 0x7;
1461	    static const char * const states[] = {
1462	      "Stopped", "Running(FetchDesc)", "Running(WaitEnd)",
1463	      "Running(ReadData/RxWait)", "Suspended(RxUnavail)",
1464	      "Running(CloseDesc)", "Running(FlushRx)", "Running(QueueRx)"
1465	    };
1466	
1467	    syslog(LOG_INFO,
1468	           "sg2000_eth: DMA state CSR5=0x%08" PRIX32
1469	           " CSR6=0x%08" PRIX32 "\n"
1470	           "  TX_FSM=%u(%s) RX_FSM=%u(%s)\n"
1471	           "  TX_DESC[0]=0x%08" PRIX32 " RX_DESC[0]=0x%08" PRIX32 "\n",
1472	           csr5, csr6,
1473	           tx_state, states[tx_state],
1474	           rx_state, states[rx_state],
1475	           priv->tx_desc[0].des0, priv->rx_desc[0].des0);
1476	  }
1477	
1478	  up_enable_irq(priv->irq);
1479	  netdev_lower_carrier_on(dev);
1480	
1481	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1482	         priv->speed, priv->duplex ? "Full" : "Half");
1483	
1484	  /* Run minimal HW TX verification before returning to upper half */
1485	
1486	  sg2000_eth_tx_test();
1487	
1488	  return OK;
1489	}
