1492	 * Name: netdriver_ifdown
1493	 *
1494	 * Description:
1495	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1496	 *
1497	 ****************************************************************************/
1498	
1499	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1500	{
1501	  FAR struct sg2000_eth_priv_s *priv =
1502	      (FAR struct sg2000_eth_priv_s *)dev;
1503	  uint32_t v;
1504	
1505	  up_disable_irq(priv->irq);
1506	
1507	  /* Stop TX and RX DMA via CSR6 (DMA_CONTROL at 0x1018).
1508	   * Clear ST (bit 13) and SR (bit 1).
1509	   */
1510	
1511	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1512	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1513	           priv->gmac_base + DMA_CONTROL);
1514	
1515	  /* Disable MAC TX/RX */
1516	
1517	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1518	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1519	           priv->gmac_base + GMAC_CONFIG);
1520	
1521	  netdev_lower_carrier_off(dev);
1522	
1523	  ninfo("netdriver_ifdown: interface down\n");
1524	
1525	  return OK;
1526	}
