1150	 * Name: sg2000_eth_tx_test
1151	 *
1152	 * Description:
1153	 *   Minimal hardware TX verification test.
1154	 *   Bypasses the network stack — directly programs a TX descriptor,
1155	 *   rings the doorbell, and verifies the DMA engine can:
1156	 *     Layer 1: Fetch the descriptor from DDR  (OWN bit cleared)
1157	 *     Layer 2: Read buffer data correctly     (no Underflow)
1158	 *     Layer 3: Generate TX Complete interrupt  (CSR5 TI bit)
1159	 *
1160	 *   Prerequisite: ifup has completed (PHY up, DMA running).
1161	 *
1162	 ****************************************************************************/
1163	
1164	static int sg2000_eth_tx_test(void)
1165	{
1166	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1167	  unsigned int idx = priv->tx_cur;
1168	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1169	  uint32_t csr5_before;
1170	  uint32_t csr5_after;
1171	  uint32_t csr6;
1172	  int timeout;
1173	  int test_len = 64;
1174	  int ret = 0;
1175	
1176	  /* STEP 0: Pre-flight checks */
1177	
1178	  if (!priv->link_up)
1179	    {
1180	      syslog(LOG_ERR, "tx_test: PHY link down, cannot test\n");
1181	      return -ENETDOWN;
1182	    }
1183	
1184	  if (desc->des0 & DESC_OWN)
1185	    {
1186	      syslog(LOG_ERR, "tx_test: desc[%u] OWN=1, ring busy\n", idx);
1187	      return -EBUSY;
1188	    }
1189	
1190	  syslog(LOG_INFO,
1191	         "=== sg2000_eth TX hardware test ===\n"
1192	         "  tx_desc[%u]=%p  tx_buf=%p  test_len=%d\n",
1193	         idx, desc, priv->tx_buf[idx], test_len);
1194	
1195	  /* STEP 1: Build a minimal broadcast ARP frame.
1196	   * dst=ff:ff:ff:ff:ff:ff  src=our MAC  type=0x0806  payload=0xAA
1197	   */
1198	
1199	  memset(priv->tx_buf[idx], 0, test_len);
1200	  memset(priv->tx_buf[idx], 0xff, 6);
1201	  memcpy(priv->tx_buf[idx] + 6, priv->mac_addr, 6);
1202	  priv->tx_buf[idx][12] = 0x08;
1203	  priv->tx_buf[idx][13] = 0x06;
1204	  memset(priv->tx_buf[idx] + 14, 0xaa, test_len - 14);
1205	
1206	  /* STEP 2: Snapshot hardware state before submission */
1207	
1208	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
1209	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1210	
1211	  syslog(LOG_INFO,
1212	         "tx_test: BEFORE doorbell\n"
1213	         "  desc des0=0x%08" PRIX32 " des2=0x%08" PRIX32 "\n"
1214	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
1215	         " TX_FSM=%u\n",
1216	         desc->des0, desc->des2, csr5_before, csr6,
1217	         (csr5_before >> 20) & 0x7);
1218	
1219	  /* Clear stale TI / TU / ETI from CSR5 so the test starts clean.
1220	   * These bits may have been set during DMA init (TU fires when DMA
1221	   * finds all TX descriptors with OWN=0).  Without clearing, the
1222	   * polling loop would see a stale TI and report false success.
1223	   */
1224	
1225	  {
1226	    uint32_t csr5_clear = DMA_STATUS_TI | DMA_STATUS_TU |
1227	                          DMA_STATUS_UNF | DMA_STATUS_TPS |
1228	                          DMA_STATUS_TJT;
1229	    putreg32(csr5_clear, priv->gmac_base + DMA_STATUS);
1230	  }
1231	
1232	  /* Flush the CSR5 write to device before proceeding.
1233	   * DMA_STATUS is a device register — need fence to ensure the
1234	   * clear is visible before the descriptor OWN=1 is visible.
1235	   */
1236	
1237	  __asm__ volatile ("fence w,o" ::: "memory");
1238	
1239	  /* STEP 3: Program TX descriptor.
1240	   *   des2 = buffer physical address
1241	   *   des1 = len | FS | LS | IC (preserve TER)
1242	   *   des0 = OWN (hand to DMA)
1243	   */
1244	
1245	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
1246	  desc->des1 = (uint32_t)test_len | TX_DESC_FS | TX_DESC_LS |
1247	               TX_DESC_IC | (desc->des1 & TX_DESC_TER);
1248	  desc->des0 = DESC_OWN;
1249	
1250	  /* STEP 4: Flush D-cache to DDR.
1251	   *   DMA reads from DDR, not from CPU cache.
1252	   *   Without this, DMA sees stale descriptor values.
1253	   *   1. DCACHE.CALL: clean all dirty D-cache lines to DDR
1254	   *   2. SYNC.S: ensure cache operations complete
1255	   *   3. fence w,o: order memory writes before device register write
1256	   */
1257	
1258	  C906_DCACHE_CALL();
1259	  C906_SYNC_S();
1260	  C906_DMA_FENCE();
1261	
1262	  syslog(LOG_INFO, "tx_test: D-cache flushed, ringing TX doorbell...\n");
1263	
1264	  /* STEP 5: Ring TX doorbell */
1265	
1266	  tx_doorbell(priv);
1267	
1268	  /* STEP 6: Wait for TX completion.
1269	   *   Poll until DMA clears OWN AND TI bit is set, or timeout.
1270	   */
1271	
1272	  timeout = 50000;
1273	
1274	  while (--timeout > 0)
1275	    {
1276	      /* Invalidate D-cache so we read DMA's write-back, not
1277	       * the stale cached value (OWN=1) that we flushed earlier.
1278	       */
1279	
1280	      C906_DCACHE_CIAL();
1281	      C906_SYNC_S();
1282	
1283	      csr5_after = getreg32(priv->gmac_base + DMA_STATUS);
1284	
1285	      if (!(desc->des0 & DESC_OWN) && (csr5_after & DMA_STATUS_TI))
1286	        {
1287	          break;
1288	        }
1289

